    }

@Override
    public void incomingDamageEvent(LivingDamageEvent.Pre event, LivingEntity attacker, LivingEntity target, ItemStack stack) {
        if (event.getSource().is(MalumTags.DamageTypes.GLEEFUL_TARGET_BLACKLIST)) {
            return;
        }
        var gleefulTarget = target.getEffect(MalumMobEffects.GLEEFUL_TARGET);
        int addedAmount = (int) (100 * target.getAttributeValue(MalumAttributes.ARCANE_RESONANCE));
        if (gleefulTarget == null) {
            target.addEffect(new MobEffectInstance(MalumMobEffects.GLEEFUL_TARGET, addedAmount * 4, 0, true, true, true));
        }
        else {
            EntityHelper.extendEffect(gleefulTarget, target, addedAmount, 36000);
        }
    }

public void damageTargets(LivingEntity wrathBearer, @Nullable LivingEntity excludedTarget, ResourceKey<DamageType> damageType, float damage) {
        var targets = new ArrayList<>(visibleTargets.values());
        Collections.shuffle(targets);

        for (int i = 0; i < targets.size(); i++) {
            LivingEntity target = targets.get(i);
            if (target.equals(excludedTarget)) {
                continue;
            }
            if (target.isAlive()) {
                var color = new MalumNetworkedParticleEffectColorData(MalumSpiritTypes.WICKED_SPIRIT, MalumSpiritTypes.ELDRITCH_SPIRIT);
                WorldEventHandler.addWorldEvent(target.level(),
                        new DelayedDamageWorldEvent(target)
                                .setMagicDamageType(damageType)
                                .setImpactParticleEffect(MalumParticleEffectTypes.INVERTED_HEART_IMPACT, color)
                                .setSound(MalumSoundEvents.INVERTED_HEART_IMPACT, 1f, 2f, 0.5f)
                                .setAttacker(wrathBearer)
                                .setDamageData(0, damage, 8 + i * 2));
            }
        }
    }

